-- BOM cho hộp quà macaron: một hộp 6 vị và một hộp 12 chiếc.
INSERT INTO recipe_items (recipe_id, stock_item_id, quantity, uom_id, notes)
SELECT r.recipe_id, si.stock_item_id, v.quantity, u.uom_id, 'Định lượng đóng gói demo.'
FROM (VALUES
('RTL-MAC-BOX6','FG_MAC_HOUJICHA',2,'EA'),('RTL-MAC-BOX6','FG_MAC_OOLONG',1,'EA'),('RTL-MAC-BOX6','FG_MAC_IRON_GODDESS',1,'EA'),('RTL-MAC-BOX6','FG_MAC_TRUFFLE',1,'EA'),('RTL-MAC-BOX6','FG_MAC_LONGJING',1,'EA'),('RTL-MAC-BOX6','PACK_MACARON_BOX',1,'EA'),
('RTL-MAC-BOX12','FG_MAC_HOUJICHA',3,'EA'),('RTL-MAC-BOX12','FG_MAC_OOLONG',3,'EA'),('RTL-MAC-BOX12','FG_MAC_IRON_GODDESS',2,'EA'),('RTL-MAC-BOX12','FG_MAC_TRUFFLE',2,'EA'),('RTL-MAC-BOX12','FG_MAC_LONGJING',2,'EA'),('RTL-MAC-BOX12','PACK_MACARON_BOX',1,'EA')
) AS v(product_sku, stock_item_code, quantity, uom_code)
JOIN products p ON p.sku=v.product_sku
JOIN recipes r ON r.product_id=p.product_id AND r.recipe_version='SIM-1'
JOIN stock_items si ON si.stock_item_code=v.stock_item_code
JOIN units_of_measure u ON u.uom_code=v.uom_code
ON CONFLICT (recipe_id, stock_item_id) DO UPDATE SET quantity=EXCLUDED.quantity, uom_id=EXCLUDED.uom_id, notes=EXCLUDED.notes;
